2.query:
timeseries value = avg(aerospike_sindex_entries, filter: { cluster_name == $cluster }), by: { cluster_name, service, sindex }
| summarize value = count(), by: { sindex } | fieldsAdd value = 1
| summarize value = count()

12.query:
timeseries value = avg(aerospike_namespace_sindex_used_bytes, filter: { cluster_name == $cluster and in(ns, array($namespace)) and storage_engine == "pmem" }), by: { cluster_name, ns, service, sindex, storage_engine }
| summarize value = count(), by: { sindex } | fieldsAdd value = 1
| summarize value = count()
| fieldsRename pmem = value
| append [
  timeseries value = avg(aerospike_namespace_sindex_used_bytes, filter: { cluster_name == $cluster and in(ns, array($namespace)) and storage_engine == "device" }), by: { cluster_name, ns, service, sindex, storage_engine }
  | summarize value = count(), by: { sindex } | fieldsAdd value = 1
  | summarize value = count()
  | fieldsRename device = value
]
| append [
  timeseries value = avg(aerospike_namespace_sindex_used_bytes, filter: { cluster_name == $cluster and in(ns, array($namespace)) and storage_engine == "memory" }), by: { cluster_name, ns, service, sindex, storage_engine }
  | summarize value = count(), by: { sindex } | fieldsAdd value = 1
  | summarize value = count()
  | fieldsRename memory = value
]

23.query:
timeseries a0 = sum(aerospike_namespace_si_query_long_basic_complete, filter: { cluster_name == $cluster and in(ns, array($namespace)) }, rate: 1s), a1 = sum(aerospike_namespace_si_query_long_basic_abort, filter: { cluster_name == $cluster and in(ns, array($namespace)) }, rate: 1s), a2 = sum(aerospike_namespace_si_query_long_basic_error, filter: { cluster_name == $cluster and in(ns, array($namespace)) }, rate: 1s), by: { cluster_name, ns, service, storage_engine }
| fieldsAdd completed = a0[], aborted = a1[], errors = a2[]
| fieldsRemove a0, a1, a2

